class Donation
class StateChapter
class DistrictChapter
class Member {
  status
}
interface Notification
class MembershipApplication {
  status
}
class Committee
class Mandate {
  termOfOffice
}
class Campaign
class Deployment {
  hours
}
StateChapter "1" *-- "1..*" DistrictChapter : consistsOf
DistrictChapter "1" *-- "1..*" Member : members
Member --|> Notification
DistrictChapter "1" -- "0..*" MembershipApplication : receives
MembershipApplication "1" --> "1" Member : creates
Committee "1" -- "0..*" Mandate : awards
Mandate "1" -- "1" Member : recipient
DistrictChapter "1" *-- "0..*" Campaign : runs
Campaign "1" *-- "0..*" Deployment : deployments
Deployment "*" -- "1" Member : participant
Payment <|-- MembershipFeePayment
Payment <|-- Donation
Payment "1" -- "1" Member : originatesFrom
Donation "0..1" -- "0..1" Campaign : earmarkedFor
@enduml

